  comparisons: [
    {"title": "Sama-sama berhubungan dengan ketidakmungkinan/kesulitan, tetapi fokusnya berbeda", "items": [{"bun": "〜っこない", "point": "っこない = mustahil; penolakan/ketidakmungkinan yang tegas dan emosional."}, {"bun": "〜かねない", "point": "かねない = justru mungkin terjadi, tetapi hasilnya buruk (bukan 'tidak mungkin')."}, {"bun": "〜かねる", "point": "かねる = tidak sanggup/tidak dapat melakukan; penolakan halus dan formal."}, {"bun": "〜がたい", "point": "がたい = sangat sulit diterima/dilakukan secara batin atau psikologis."}, {"bun": "〜ようがない", "point": "ようがない = tidak ada cara/metode untuk melakukannya."}]},
    {"title": "Sama-sama berarti 'wajar', tetapi yang dinilai berbeda", "items": [{"bun": "〜て当然だ (〜てとうぜんだ)", "point": "て当然だ = suatu hasil/keadaan memang pantas atau wajar terjadi."}, {"bun": "〜のももっともだ", "point": "のももっともだ = reaksi/perasaan seseorang dapat dimaklumi."}]},
    {"title": "Keduanya berarti 'bukan hanya A, tetapi juga B'", "items": [{"bun": "〜ばかりか", "point": "ばかりか = lebih umum; menambahkan hal yang lebih jauh/mengejutkan."}, {"bun": "〜のみならず", "point": "のみならず = lebih formal; sering dipakai dalam tulisan atau penjelasan."}]},
    {"title": "Keduanya menyatakan konsekuensi/tanggung jawab setelah suatu keputusan atau kondisi", "items": [{"bun": "〜以上(は)", "point": "以上(は) = karena faktanya sudah demikian, sewajarnya ada tanggung jawab."}, {"bun": "〜からには", "point": "からには = karena sudah memilih/memutuskan, harus menuntaskan konsekuensinya; tekad lebih terasa."}]},
    {"title": "Ketiganya berarti 'dari sudut pandang', dengan titik tekan yang sedikit berbeda", "items": [{"bun": "〜から言うと / 〜から言えば", "point": "から言うと = penilaian dari posisi/peran atau sudut pandang tertentu."}, {"bun": "〜からすると / 〜からすれば/~からしたら", "point": "からすると = penilaian atau dugaan berdasarkan sudut pandang maupun petunjuk/bukti."}, {"bun": "〜から見ると / 〜から見れば", "point": "から見ると = secara harfiah 'jika dilihat dari'; menyoroti perspektif pengamat."}]},
    {"title": "Mirip bentuknya, tetapi hubungan maknanya berbeda", "items": [{"bun": "〜にも関わらず (にもかかわらず)", "point": "にもかかわらず = 'meskipun/padahal'; hasil B berlawanan dengan fakta A."}, {"bun": "〜に関わらず / 〜に関わりなく (にかかわらず / にかかわりなく)", "point": "にかかわらず = 'terlepas dari'; kondisi A tidak memengaruhi berlakunya B."}, {"bun": "〜を問わず (をとわず)", "point": "を問わず = 'tanpa memandang'; tidak membedakan kategori/batasan, sering untuk syarat atau cakupan."}]},
    {"title": "Sama-sama berkaitan dengan dasar, tetapi jenis dasarnya berbeda", "items": [{"bun": "〜ことから", "point": "ことから = fakta/keadaan menjadi alasan atau asal-usul kesimpulan/nama."}, {"bun": "〜に基づいて (にもとづいて)", "point": "に基づいて = tindakan/keputusan berlandaskan aturan, data, atau fakta."}, {"bun": "〜をもとに / 〜をもとにして", "point": "をもとに = sesuatu dipakai sebagai bahan/sumber untuk membuat atau mengembangkan hal lain."}]},
    {"title": "Ketiganya berarti 'pada saat/ketika' dan bernuansa formal", "items": [{"bun": "〜に際して (〜にさいして)", "point": "に際して = pada kesempatan/peristiwa penting; sering sebagai pengantar tindakan."}, {"bun": "〜折には (〜おりには)", "point": "折には = pada kesempatan tertentu; sopan/formal, sering dalam surat atau bisnis."}, {"bun": "〜際に / 〜際 (〜さいに)", "point": "際に = pada saat melakukan/terjadi sesuatu; lebih formal daripada とき."}]},
    {"title": "Keduanya berarti 'berawal dari/pemicu'", "items": [{"bun": "〜をきっかけに / 〜をきっかけにして", "point": "きっかけに = pemicu atau kesempatan yang memulai perubahan; lebih umum."}, {"bun": "〜を契機に / 〜を契機として (〜をけいきに)", "point": "契機に = titik balik/pemicu penting; lebih formal dan sering menekankan perubahan besar."}]},
    {"title": "Keduanya dapat diterjemahkan 'tidak ada cara', tetapi maksudnya berbeda", "items": [{"bun": "〜ほかない", "point": "ほかない = tidak ada pilihan lain selain melakukan A."}, {"bun": "〜ようがない", "point": "ようがない = tidak ada cara/metode untuk melakukan A."}]},
    {"title": "Sama-sama bisa diterjemahkan 'tetapi', tetapi hubungan kalimatnya berbeda", "items": [{"bun": "それなのに", "point": "それなのに = kenyataan B bertentangan dengan fakta A; sering ada rasa kecewa/heran."}, {"bun": "それでも", "point": "それでも = meski ada keadaan A, keputusan/tindakan B tetap dilakukan."}, {"bun": "だが", "point": "だが = pertentangan umum antarpernyataan: tetapi."}, {"bun": "ただし / ただ", "point": "ただし = memberi syarat atau pengecualian."}, {"bun": "もっとも", "point": "もっとも = memberi catatan/koreksi yang membatasi pernyataan sebelumnya."}]},
    {"title": "Kata sambung untuk urutan/sebab-akibat; jangan disamakan", "items": [{"bun": "それで", "point": "それで = A menjadi sebab, B menjadi akibat."}, {"bun": "それで / で", "point": "それで (percakapan) = 'terus?' untuk meminta cerita dilanjutkan."}, {"bun": "そこで", "point": "そこで = sebagai respons atas situasi A, dilakukan tindakan/solusi B."}, {"bun": "したがって", "point": "したがって = kesimpulan logis berdasarkan A; lebih formal."}, {"bun": "すると", "point": "すると = setelah A terjadi/dilakukan, kemudian muncul B."}]},
    {"title": "Ketiganya mengalihkan/menambahkan topik, tetapi fungsi percakapannya berbeda", "items": [{"bun": "そういえば", "point": "そういえば = 'ngomong-ngomong'; teringat sesuatu yang berkaitan."}, {"bun": "それはそうと", "point": "それはそうと = 'terlepas dari itu'; berpindah ke topik lain."}, {"bun": "ちなみに", "point": "ちなみに = memberi informasi tambahan yang masih berkaitan."}]},
    {"title": "Ketiganya dapat berhubungan dengan akibat, tetapi jenis hubungan berbeda", "items": [{"bun": "それで", "point": "それで = sebab A menghasilkan akibat B."}, {"bun": "したがって", "point": "したがって = B merupakan kesimpulan logis dari A."}, {"bun": "そこで", "point": "そこで = B adalah tindakan/solusi yang diambil sebagai respons terhadap A."}]}
  ]
